# Plant layout diagram (Línea 1) -- same image used in the Grafana canvas panel,
# re-encoded as JPEG (was a 1.57MB PNG with no real transparency) and embedded as
# base64, same reasoning as the logo: Fusion's Streamlit editor has no binary-asset upload.
PLANT_IMAGE_B64 = ""

# x/y are in the SAME data-coordinate space main.py's x/y axes use (image
# spans data x:[0,1] y:[0,1], y=0 at the image's own bottom edge, y=1 at its
# top -- main.py flips these image-relative fractions with `1 - el["y"]` so
# 0 still means "top of image" here). Empty on Línea 3: every group here is
# shown per machine instead (PRINTER/STANDUM/ISPRAY_MACHINE_CODES below),
# and MINSTER has its own below-image box (MINSTER_X/Y). Kept so main.py
# stays identical in structure to linea1_plant_view's.
#
# NOTE: image-relative y fractions anywhere in this file are relative to
# PLANT_IMAGE_B64's own height (cropped from 966px to
# PLANT_IMAGE_HEIGHT=851px, removing pure black padding below the
# "MINSTER"/"STANDUM" text). If the image is ever re-cropped or swapped,
# rescale them by (old_height / new_height).
ELEMENTS = []

# Native dimensions of the (cropped) PLANT_IMAGE_B64 -- main.py derives its
