STANDUM_MACHINE_CODES = [f"STANDUM{n}" for n in range(31, 39)]
STANDUM_COLUMN_X = [0.26 + 0.09 * i for i in range(8)]
STANDUM_ROW_Y = {"number": -0.002, "production": -0.05, "scrap": -0.115}
STANDUM_NUMBER_BOX_WIDTH = 46
STANDUM_NUMBER_BOX_HEIGHT = 28
STANDUM_VALUE_BOX_WIDTH = 76  # +11px border/padding as rendered; leaves a gap at 0.09 spacing
