ISPRAY_MACHINE_CODES = [f"ISPRAY{n}" for n in range(31, 39)]
ISPRAY_COLUMN_X = [0.04 + 0.072 * i for i in range(8)]
ISPRAY_ROW_Y = {"number": 0.995, "production": 0.947}
ISPRAY_VALUE_BOX_WIDTH = 58  # +11px border/padding as rendered; leaves a gap at 0.072 spacing
# The "ISPRAY" caption is erased from PLANT_IMAGE_B64 and drawn as a text
# annotation centered over the column row instead, so it always sits right
