def current_shift_label(now_local: datetime = None) -> str:
    """"Turno actual" label for display -- day shift 06:00-18:00 local,
    night shift 18:00-06:00, matching the shift convention used everywhere
    else in this project."""
    now_local = now_local or datetime.now(LOCAL_TZ)
    if 6 <= now_local.hour < 18:
        return "1er turno (día)"
    return "2do turno (noche)"


def current_shift_key() -> tuple[str, str]:
    """(date_str, shift_code) for the shift currently running, matching the
    report_{code}_{date}_{shift}_entry_NN external_id convention used by
    functions/hourly_production_report and overview_dashboard/cdf_service.py.
    Night shift crosses midnight, so between 00:00-06:00 local this
    correctly returns YESTERDAY's date with "night" (a night-shift report
    written at 01:00 is filed under the previous day everywhere else in
    this project).

    date_str is compact YYYYMMDD (e.g. "20261002"), exactly as
    hourly_production_report's _shift_context writes it into the
    external_id -- a dashed YYYY-MM-DD never matches any event, which left
    every per-machine box stuck at 0."""
    now_local = datetime.now(LOCAL_TZ)
    if 6 <= now_local.hour < 18:
        return now_local.date().strftime("%Y%m%d"), "day"
    shift_date = now_local.date() if now_local.hour >= 18 else now_local.date() - timedelta(days=1)
    return shift_date.strftime("%Y%m%d"), "night"
